/**
 * Thin wrapper around window.tableau.extensions.initializeAsync().
 * Resolves immediately when Tableau runtime is absent (dev/test environment).
 */

type TableauExtensions = {
  extensions: {
    initializeAsync: () => Promise<void>;
  };
};

declare global {
  interface Window {
    tableau?: TableauExtensions;
  }
}

let initialized = false;

export async function initializeExtension(): Promise<void> {
  if (typeof window === 'undefined' || !window.tableau) {
    // No Tableau runtime — running in dev/test outside Tableau Desktop/Cloud.
    // Resolve immediately so the extension shell renders normally.
    return;
  }
  if (initialized) return;
  initialized = true;
  await window.tableau.extensions.initializeAsync();
}

/**
 * Backend HTTP client. All fetch calls go through apiFetch.
 * Errors always surface as ApiError — never raw fetch rejections or non-2xx responses.
 * JSON fields from the API are snake_case; camelCase conversion happens at the call site.
 */

const BACKEND_URL = (import.meta.env.VITE_BACKEND_URL as string | undefined) || 'http://localhost:8000';

export class ApiError extends Error {
  constructor(
    public readonly code: string,
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = 'ApiError';
  }
}

export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response;
  try {
    response = await fetch(`${BACKEND_URL}${path}`, {
      ...init,
      headers: {
        'Content-Type': 'application/json',
        ...init?.headers,
      },
    });
  } catch {
    throw new ApiError('NETWORK_ERROR', 'Unable to reach the autom9 backend', 0);
  }

  if (!response.ok) {
    let code = 'UNKNOWN_ERROR';
    let message = `Request failed with status ${response.status}`;
    try {
      const body = (await response.json()) as { error?: { code?: string; message?: string } };
      code = body?.error?.code ?? code;
      message = body?.error?.message ?? message;
    } catch {
      // non-JSON error body — keep defaults
    }
    throw new ApiError(code, message, response.status);
  }

  try {
    return (await response.json()) as T;
  } catch {
    throw new ApiError('INVALID_RESPONSE', 'Server returned a non-JSON response', response.status);
  }
}

